import sys

def cs2_brute(cands, target):
    cands = sorted(cands)
    res = []
    def dfs(i, remain, path):
        if remain == 0:
            res.append(path[:])
            return
        for j in range(i, len(cands)):
            if j > i and cands[j] == cands[j - 1]:
                continue
            x = cands[j]
            if x > remain:
                break
            path.append(x)
            dfs(j + 1, remain - x, path)
            path.pop()
    dfs(0, target, [])
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    cands = list(map(int, data[1:1 + n]))
    target = int(data[1 + n])
    res = cs2_brute(cands, target)
    for comb in res:
        print(' '.join(map(str, comb)))

import sys

def cs2_best(cands, target):
    cands = sorted(cands)
    res = []
    def dfs(i, remain, path):
        if remain == 0:
            res.append(path[:])
            return
        for j in range(i, len(cands)):
            x = cands[j]
            if x > remain:
                break
            if j > i and cands[j - 1] == x:
                continue
            path.append(x)
            dfs(j + 1, remain - x, path)
            path.pop()
    dfs(0, target, [])
    return sorted(res)

